// Evento já validado pelo backend (HMAC, messageId, botEnabled, handoff).
// O n8n NÃO valida Meta — o backend é o gateway de segurança.
// Payload: { event, messageId, phone, name, text, timestamp, conversationId, integrationId, customerId, state, mode, currentIntent, currentStep }
const item = $input.first().json;
if (!item.text || !item.phone) {
  throw new Error('text e phone são obrigatórios');
}
return [{ json: item }];

// Normalização: extrai intenção de forma determinística.
// Nenhuma regra de negócio aqui — apenas classificação de intenção.
const item = $input.first().json;
const text = String(item.text || '').toLowerCase();
let intent = 'UNKNOWN';
if (/menu|cardapio|cardápio|o que vocês tem|o que tem|opções|opcoes/i.test(text)) intent = 'MENU';
else if (/quero|pedir|adiciona|adicionar|gostaria de/i.test(text)) intent = 'ORDER';
else if (/carrinho|meu pedido/i.test(text)) intent = 'CART';
else if (/atendente|humano|pessoa|falar com alguém/i.test(text)) intent = 'HUMAN';
else if (/oi|ola|olá|bom dia|boa tarde|boa noite|começar/i.test(text)) intent = 'START';
return [{ json: { ...item, intent } }];

// Encaminha para o backend King Food processar (fonte da verdade).
// O backend decide: preço, delivery, cupom, total, disponibilidade, status.
// O n8n NUNCA calcula regra de negócio.
return $input.all();

// Retorna a resposta pronta para o backend enviar pela Meta.
// Formato: { reply: string }
const item = $input.first().json;
const reply = item.reply || item.text || item.output || '';
if (!reply) throw new Error('backend não retornou resposta');
return [{ json: { reply } }];
